import{_ as s,a0 as u,w as a,s as r,ao as d,I as i,x as n,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"每日Ubuntu小技巧：合上笔记本，系统不睡眠 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：合上笔记本，系统不睡眠 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：合上笔记本，系统不睡眠 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：合上笔记本，系统不睡眠 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Daily Ubuntu Tips – Do Nothing When Laptop Lid Is Closed","title":"每日Ubuntu小技巧：合上笔记本，系统不睡眠","tag":"201401","desc":""},"relativePath":"201401/Daily Ubuntu Tips – Do Nothing When Laptop Lid Is Closed.md","filePath":"[post].md"}'),l={name:"201401/Daily Ubuntu Tips – Do Nothing When Laptop Lid Is Closed.md"};function g(b,t,T,m,f,C){const e=u("Link");return a(),r("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-合上笔记本-系统不睡眠" tabindex="-1">每日Ubuntu小技巧：合上笔记本，系统不睡眠 <a class="header-anchor" href="#每日ubuntu小技巧-合上笔记本-系统不睡眠" aria-label="Permalink to “每日Ubuntu小技巧：合上笔记本，系统不睡眠”">​</a></h1><p>Ubuntu 是一个处在牛 A 和牛 C 之间的现代操作系统，全世界数百万用户和公司都在使用它。无论是充当工作台还是高级工程机器，Ubuntu 都游刃有余。</p><p>如果你是 Ubuntu 初学者，使用过程还需要高手指导，那就关注本站吧。我们已经写了数百篇 Ubuntu 教程，足以带你入门。从安装 Ubuntu 到系统基本设置，我们都有涉猎。</p><p>这篇简单的教程为你介绍当笔记本盖子合上时该干嘛还是干嘛，而不是进入睡眠模式或者直接关机。</p><p>大多数现代操作系统（包括 Windows）会在笔记本合上时进入睡眠状态。Ubuntu 也是如此。如果你想让你的笔记本盖子合上时不睡眠，就跟着我们学习吧。</p><p>要达到这个目的，Ubuntu 有两种方法。第一种是打开 <strong>System Settings –&gt; Power</strong>（中文版是打开 <strong>系统设置 -&gt; 电源</strong>），然后进行设置。一些用户设置后不会生效。</p><p>另一个方法是直接编辑 Login Manager 的配置文件（<strong>logind.conf</strong>）。这个方法基本能生效，建议使用这个。</p><p>要开始了，按下 <strong>Ctrl – Alt – T</strong> 组合键，打开终端。然后运行下面的命令打开 logind.conf 文件。你的所有修改都在这个文件内。</p><pre><code>sudo gedit /etc/systemd/logind.conf
</code></pre><p>打开文件后修改下面这行：</p><pre><code>#HandleLidSwitch=suspend
</code></pre><p>改成这样：</p><pre><code>HandleLidSwitch=ignore
</code></pre><p>保存文件，重启 Login Manager 服务：</p><pre><code>sudo restart systemd-logind
</code></pre><p>工作完成！</p><p>配置文件的 “ignore” 值告诉 Ubuntu 当笔记本合上后不要睡眠或挂起。不要改动其它设置然后保存文件。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/photo.jpg" alt=""></p><hr>`,19)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-do-nothing-when-laptop-lid-is-closed/"},{default:p(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-do-nothing-when-laptop-lid-is-closed/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=n("译者：",-1)),o(e,{href:"https://github.com/bazz2"},{default:p(()=>[...t[2]||(t[2]=[n("bazz2",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),o(e,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const h=s(l,[["render",g]]);export{U as __pageData,h as default};
